1	import { supabase } from '../lib/supabase';
2	import { invokeFunction } from './api';
3	import { logError } from '../lib/logger';
4	
5	export interface Wallet {
6	    id: string;
7	    user_id: string;
8	    balance: number;
9	    user_type: 'company' | 'worker';
10	    asaas_customer_id?: string;
11	    created_at: string;
12	    updated_at: string;
13	}
14	
15	export interface WalletTransaction {
16	    id: string;
17	    wallet_id: string;
18	    amount: number;
19	    type: 'credit' | 'debit' | 'escrow_reserve' | 'escrow_release' | 'initial_balance' | 'platform_fee' | 'escrow_authorize';
20	    description: string | null;
21	    reference_id: string | null;
22	    created_at: string;
23	}
24	
25	export interface EscrowTransaction {
26	    id: string;
27	    job_id: string;
28	    application_id: string | null;
29	    amount: number;
30	    company_wallet_id: string;
31	    worker_wallet_id: string | null;
32	    // Postpago (Slice 2): 'authorized'/'captured' coexistem com os estados prepago.
33	    status: 'reserved' | 'authorized' | 'captured' | 'released' | 'refunded';
34	    // prepaid = pull legado (saldo); postpaid = push Slice 2 (hold no cartão). Default 'prepaid' no DB.
35	    kind?: 'prepaid' | 'postpaid';
36	    // id da cobrança no Asaas (authorizeOnly:true). NULL para prepago.
37	    asaas_payment_id?: string | null;
38	    authorized_at?: string | null;
39	    captured_at?: string | null;
40	    created_at: string;
41	    released_at: string | null;
42	    job?: { title: string };
43	}
44	
45	export const WalletService = {
46	    async getOrCreateWallet(userId: string, userType: 'company' | 'worker'): Promise<Wallet | null> {
47	        const { data: existing } = await supabase
48	            .from('wallets')
49	            .select('*')
50	            .eq('user_id', userId)
51	            .single();
52	
53	        if (existing) return existing as Wallet;
54	
55	        const { data: newWallet, error } = await supabase
56	            .from('wallets')
57	            .insert({ user_id: userId, balance: 0.00, user_type: userType })
58	            .select()
59	            .single();
60	
61	        if (error) {
62	            logError('Error creating wallet', error);
63	            return null;
64	        }
65	
66	        return newWallet as Wallet;
67	    },
68	
69	    async withdrawFunds(amount: number, pixKey: string, pixKeyType: string = 'CPF'): Promise<{ success: boolean; error?: string }> {
70	        try {
71	            await invokeFunction('asaas-withdraw', { amount, pixKey, pixKeyType });
72	            return { success: true };
73	        } catch (error: unknown) {
74	            logError('Error withdrawing funds', error);
75	            return { success: false, error: error instanceof Error ? error.message : 'Erro ao realizar saque' };
76	        }
77	    },
78	
79	    async getBalance(userId: string): Promise<number> {
80	        const { data } = await supabase
81	            .from('wallets')
82	            .select('balance')
83	            .eq('user_id', userId)
84	            .single();
85	
86	        return data?.balance || 0;
87	    },
88	
89	    async getTransactions(userId: string): Promise<WalletTransaction[]> {
90	        const { data: wallet } = await supabase
91	            .from('wallets')
92	            .select('id')
93	            .eq('user_id', userId)
94	            .single();
95	
96	        if (!wallet) return [];
97	
98	        const { data } = await supabase
99	            .from('wallet_transactions')
100	            .select('*')
101	            .eq('wallet_id', wallet.id)
102	            .order('created_at', { ascending: false });
103	
104	        return (data || []) as WalletTransaction[];
105	    },
106	
107	    async reserveEscrow(jobId: string, amount: number, companyUserId: string): Promise<{ success: boolean; error?: string }> {
108	        try {
109	            const { error: rpcError } = await supabase.rpc('reserve_escrow', {
110	                p_job_id: jobId,
111	                p_amount: amount,
112	                p_company_user_id: companyUserId
113	            });
114	
115	            if (rpcError) {
116	                if (rpcError.message?.includes('Saldo insuficiente')) {
117	                    return { success: false, error: rpcError.message };
118	                }
119	                if (rpcError.message?.includes('Carteira nao encontrada')) {
120	                    return { success: false, error: 'Carteira nao encontrada' };
121	                }
122	                if (rpcError.code === '23505') {
123	                    return { success: false, error: 'Escrow ja existe para esta vaga' };
124	                }
125	                throw rpcError;
126	            }
127	
128	            return { success: true };
129	        } catch (error) {
130	            logError('Error reserving escrow', error);
131	            return { success: false, error: 'Erro ao reservar pagamento' };
132	        }
133	    },
134	
135	    async createDeposit(payload: { amount: number, name?: string, cpfCnpj?: string, billingType?: string }): Promise<{ paymentId?: string; invoiceUrl?: string; pixQrCodeUrl?: string; error?: string }> {
136	        try {
137	            return await invokeFunction('asaas-deposit', payload);
138	        } catch (error: unknown) {
139	            logError('Error creating deposit', error);
140	            return { error: error instanceof Error ? error.message : 'Erro ao criar deposito via Asaas' };
141	        }
142	    },
143	
144	    async syncBalance(): Promise<{ success: boolean; hasUpdates?: boolean; totalSynced?: number; message?: string; error?: string }> {
145	        try {
146	            return await invokeFunction('asaas-sync', {});
147	        } catch (error: unknown) {
148	            logError('Error syncing balance', error);
149	            return { success: false, error: error instanceof Error ? error.message : 'Erro ao sincronizar saldo' };
150	        }
151	    },
152	
153	    async releaseEscrow(jobId: string, applicationId: string, workerUserId: string): Promise<{ success: boolean; error?: string }> {
154	        try {
155	            await invokeFunction('asaas-checkout', { jobId, applicationId, workerId: workerUserId });
156	            return { success: true };
157	        } catch (error: unknown) {
158	            logError('Error releasing escrow', error);
159	            return { success: false, error: error instanceof Error ? error.message : 'Erro ao liberar pagamento' };
160	        }
161	    },
162	
163	    async refundEscrow(jobId: string, reason?: string): Promise<{ success: boolean; error?: string }> {
164	        try {
165	            const { error: rpcError } = await supabase.rpc('refund_escrow', {
166	                p_job_id: jobId,
167	                p_reason: reason || 'Reembolso de vaga cancelada'
168	            });
169	
170	            if (rpcError) {
171	                if (rpcError.message?.includes('No reserved escrow')) {
172	                    return { success: true };
173	                }
174	                throw rpcError;
175	            }
176	
177	            return { success: true };
178	        } catch (error) {
179	            logError('Error refunding escrow', error);
180	            return { success: false, error: 'Erro ao reembolsar' };
181	        }
182	    },
183	
184	    async getJobEscrow(jobId: string): Promise<EscrowTransaction | null> {
185	        const { data } = await supabase
186	            .from('escrow_transactions')
187	            .select('*')
188	            .eq('job_id', jobId)
189	            .single();
190	
191	        return data as EscrowTransaction | null;
192	    },
193	
194	    async getCompanyEscrows(companyUserId: string): Promise<EscrowTransaction[]> {
195	        const { data: wallet } = await supabase
196	            .from('wallets')
197	            .select('id')
198	            .eq('user_id', companyUserId)
199	            .single();
200	
201	        if (!wallet) return [];
202	
203	        const { data } = await supabase
204	            .from('escrow_transactions')
205	            .select('*, job:jobs(title)')
206	            .eq('company_wallet_id', wallet.id)
207	            .order('created_at', { ascending: false });
208	
209	        return (data || []) as EscrowTransaction[];
210	    }
211	};
