/**
 * asaas-tokenize-card — Tokeniza cartão de crédito da empresa no Asaas.
 *
 * Fluxo postpago (Slice 2 / ADR-20260622-pagamento-postpago):
 *  1. Garante que a empresa tem um asaas_customer_id (cria se não tiver).
 *  2. Envia dados do cartão para POST /v3/creditCard/tokenizeCreditCard (PAN só nesta
 *     chamada server→Asaas; NUNCA gravado no DB — Article 10 / PCI).
 *  3. Grava o token opaco + metadados em payment_methods (UNIQUE por company+token).
 *  4. Marca o novo método como default; desmarca o anterior.
 *
 * Deploy normal (com verify-jwt) — chamada autenticada pela empresa.
 * Article 10: service_role apenas no Deno (Supabase Admin); sem chave no frontend.
 */

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'jsr:@supabase/supabase-js@2';
import { getCorsHeaders, ASAAS_API_URL, getAsaasHeaders } from '../_shared/asaas.ts';
import { isRateLimited } from '../_shared/rate-limit.ts';

// ---------------------------------------------------------------------------
// Tipos de input
// ---------------------------------------------------------------------------

interface HolderInfo {
  name: string;
  email: string;
  cpfCnpj: string;
  postalCode: string;
  addressNumber: string;
  phone: string;
}

interface TokenizeCardInput {
  holderName: string;
  number: string;
  expiryMonth: string;
  expiryYear: string;
  ccv: string;
  holderInfo: HolderInfo;
}

// ---------------------------------------------------------------------------
// Serve
// ---------------------------------------------------------------------------

serve(async (req) => {
  const corsHeaders = getCorsHeaders(req);

  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    // --- Admin client (service_role só no Deno) ---
    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    );

    // --- Auth ---
    const authHeader = req.headers.get('Authorization');
    if (!authHeader) throw new Error('Missing Authorization header');
    const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : authHeader;
    const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(token);
    if (userError || !user) throw new Error('Invalid Token');

    // --- Rate limit: 3 tokenizações por minuto por empresa ---
    if (isRateLimited(user.id, 'tokenize-card', 3, 60_000)) {
      return new Response(
        JSON.stringify({ error: 'Muitas tentativas. Aguarde 1 minuto.' }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 429 }
      );
    }

    // --- Parse do body ---
    const body: TokenizeCardInput = await req.json();
    const { holderName, number, expiryMonth, expiryYear, ccv, holderInfo } = body;

    if (!holderName || !number || !expiryMonth || !expiryYear || !ccv) {
      throw new Error('Dados do cartão incompletos.');
    }
    if (!holderInfo?.cpfCnpj || !holderInfo?.name) {
      throw new Error('holderInfo obrigatório: name e cpfCnpj.');
    }

    // --- Resolver company_id (owner_id = auth.uid()) ---
    const { data: company, error: companyErr } = await supabaseAdmin
      .from('companies')
      .select('id')
      .eq('owner_id', user.id)
      .maybeSingle();

    if (companyErr || !company) {
      throw new Error('Perfil de empresa não encontrado.');
    }
    const companyId: string = company.id;

    // --- Garantir carteira e asaas_customer_id ---
    const { data: wallet, error: walletErr } = await supabaseAdmin
      .from('wallets')
      .select('id, asaas_customer_id')
      .eq('user_id', user.id)
      .maybeSingle();

    if (walletErr || !wallet) {
      throw new Error('Carteira não encontrada. Conclua o onboarding primeiro.');
    }

    let customerId: string = wallet.asaas_customer_id ?? '';

    // Criar customer no Asaas se não existir (mesmo padrão do asaas-deposit)
    if (!customerId) {
      const cleanDoc = holderInfo.cpfCnpj.replace(/\D/g, '');
      const customerRes = await fetch(`${ASAAS_API_URL}/customers`, {
        method: 'POST',
        headers: getAsaasHeaders(),
        body: JSON.stringify({
          name: holderInfo.name,
          cpfCnpj: cleanDoc,
          email: holderInfo.email,
          phone: holderInfo.phone,
        }),
      });
      const customerData = await customerRes.json();
      if (!customerRes.ok) {
        throw new Error(
          customerData.errors?.[0]?.description || 'Erro ao criar conta de pagamento.'
        );
      }
      customerId = customerData.id;
      await supabaseAdmin
        .from('wallets')
        .update({ asaas_customer_id: customerId })
        .eq('user_id', user.id)
        .throwOnError();
    }

    // --- remoteIp para conformidade Asaas (exigido pelo endpoint de tokenização) ---
    const remoteIp =
      req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
      req.headers.get('x-real-ip') ||
      '0.0.0.0';

    // --- Tokenizar cartão no Asaas (PAN só nesta chamada — nunca gravado) ---
    const tokenizeRes = await fetch(`${ASAAS_API_URL}/creditCard/tokenizeCreditCard`, {
      method: 'POST',
      headers: getAsaasHeaders(),
      body: JSON.stringify({
        customer: customerId,
        creditCard: {
          holderName,
          number,
          expiryMonth,
          expiryYear,
          ccv,
        },
        creditCardHolderInfo: {
          name: holderInfo.name,
          email: holderInfo.email,
          cpfCnpj: holderInfo.cpfCnpj.replace(/\D/g, ''),
          postalCode: holderInfo.postalCode.replace(/\D/g, ''),
          addressNumber: holderInfo.addressNumber,
          phone: holderInfo.phone.replace(/\D/g, ''),
        },
        remoteIp,
      }),
    });

    const tokenizeData = await tokenizeRes.json();
    if (!tokenizeRes.ok) {
      throw new Error(
        tokenizeData.errors?.[0]?.description ||
        tokenizeData.error ||
        'Cartão recusado ou dados inválidos.'
      );
    }

    const asaasCreditCardToken: string = tokenizeData.creditCardToken;
    const brand: string = tokenizeData.creditCardBrand ?? '';
    // last4: Asaas retorna creditCardNumber mascarado (ex: "•••• 1234") — extraímos os 4 últimos dígitos
    const last4Raw: string = tokenizeData.creditCardNumber ?? '';
    const last4 = last4Raw.replace(/\D/g, '').slice(-4) || null;

    if (!asaasCreditCardToken) {
      throw new Error('Asaas não retornou o token do cartão.');
    }

    // --- Desmarcar default anterior (se houver) ---
    await supabaseAdmin
      .from('payment_methods')
      .update({ is_default: false })
      .eq('company_id', companyId)
      .eq('is_default', true);

    // --- Gravar método de pagamento (idempotente: UNIQUE company_id + token) ---
    const { data: pm, error: pmErr } = await supabaseAdmin
      .from('payment_methods')
      .upsert(
        {
          company_id: companyId,
          asaas_credit_card_token: asaasCreditCardToken,
          brand: brand || null,
          last4,
          holder_name: holderName,
          is_default: true,
        },
        { onConflict: 'company_id,asaas_credit_card_token', ignoreDuplicates: false }
      )
      .select('id, brand, last4')
      .single();

    if (pmErr || !pm) {
      throw new Error('Erro ao salvar método de pagamento.');
    }

    return new Response(
      JSON.stringify({
        success: true,
        paymentMethodId: pm.id,
        brand: pm.brand,
        last4: pm.last4,
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
    );
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : 'Erro interno.';
    console.error('asaas-tokenize-card error:', msg);
    return new Response(
      JSON.stringify({ error: msg }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 400 }
    );
  }
});

/**
 * asaas-authorize-payment — Pré-autoriza (hold) o cartão da empresa no aceite do convite.
 *
 * Fluxo postpago (Slice 2 / ADR-20260622-pagamento-postpago):
 *  Chamado pelo ShiftInviteService.respondToInvite('accepted') após o status da application
 *  mudar para 'hired'. Cria o hold (authorizeOnly:true) no Asaas e grava o escrow 'authorized'
 *  no DB via RPC atômica authorize_escrow_postpago.
 *
 * Modo controlado por env ASAAS_POSTPAGO_MODE:
 *  - 'authorize' (default)    : fluxo normal pré-auth → capture.
 *  - 'charge_on_demand'       : pula a pré-auth; a captura acontece na conclusão. Neste caso
 *                               a função retorna success sem criar hold nem chamar a RPC.
 *
 * Idempotência:
 *  - idx_escrow_unique_asaas_payment (UNIQUE asaas_payment_id): reprocesso não cria 2º escrow.
 *  - 23505 do índice idx_escrow_one_authorized_per_job → tratar como já-autorizado.
 *
 * Deploy normal (com verify-jwt) — caller é o WORKER autenticado.
 * Article 10: service_role apenas no Deno.
 */

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'jsr:@supabase/supabase-js@2';
import { getCorsHeaders, ASAAS_API_URL, getAsaasHeaders } from '../_shared/asaas.ts';
import { isRateLimited } from '../_shared/rate-limit.ts';

serve(async (req) => {
  const corsHeaders = getCorsHeaders(req);

  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    );

    // --- Auth (caller = worker) ---
    const authHeader = req.headers.get('Authorization');
    if (!authHeader) throw new Error('Missing Authorization header');
    const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : authHeader;
    const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(token);
    if (userError || !user) throw new Error('Invalid Token');

    if (isRateLimited(user.id, 'authorize-payment', 5, 60_000)) {
      return new Response(
        JSON.stringify({ error: 'Muitas tentativas. Aguarde 1 minuto.' }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 429 }
      );
    }

    const { jobId, applicationId } = await req.json();
    if (!jobId || !applicationId) throw new Error('jobId e applicationId são obrigatórios.');

    // --- Verificar que o caller é o worker desta application ---
    const { data: app, error: appErr } = await supabaseAdmin
      .from('applications')
      .select('id, worker_id, job_id, status, invited_by_company_at')
      .eq('id', applicationId)
      .maybeSingle();

    if (appErr || !app) throw new Error('Candidatura não encontrada.');
    if (app.worker_id !== user.id) throw new Error('Não autorizado: esta candidatura não é sua.');
    if (app.job_id !== jobId) throw new Error('jobId não corresponde à candidatura.');
    if (!app.invited_by_company_at) {
      throw new Error('Esta candidatura não é um convite push (invited_by_company_at ausente).');
    }
    if (app.status !== 'hired') {
      throw new Error(
        `Status da candidatura deve ser 'hired' para autorizar pagamento, mas é '${app.status}'.`
      );
    }

    // --- Verificar se já existe escrow postpago para este job (idempotência) ---
    const { data: existingEscrow } = await supabaseAdmin
      .from('escrow_transactions')
      .select('id, asaas_payment_id, status')
      .eq('job_id', jobId)
      .eq('kind', 'postpaid')
      .eq('status', 'authorized')
      .maybeSingle();

    if (existingEscrow) {
      // Já autorizado — idempotência: retorna o existente sem criar 2º hold
      return new Response(
        JSON.stringify({
          success: true,
          escrowId: existingEscrow.id,
          asaasPaymentId: existingEscrow.asaas_payment_id,
          status: 'authorized',
          idempotent: true,
        }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
      );
    }

    // --- Modo: 'authorize' | 'charge_on_demand' ---
    const mode = Deno.env.get('ASAAS_POSTPAGO_MODE') ?? 'authorize';

    if (mode === 'charge_on_demand') {
      // Pula a pré-auth; captura será feita na conclusão. Retorna success sem escrow.
      console.log(`[authorize-payment] charge_on_demand mode: skip hold for job=${jobId}`);
      return new Response(
        JSON.stringify({ success: true, status: 'charge_on_demand', mode }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
      );
    }

    // --- Buscar dados do job (valor + company_id) ---
    const { data: job, error: jobErr } = await supabaseAdmin
      .from('jobs')
      .select('company_id, budget, title')
      .eq('id', jobId)
      .maybeSingle();

    if (jobErr || !job) throw new Error('Vaga não encontrada.');
    const amount: number = job.budget;
    if (!amount || amount <= 0) throw new Error('Budget da vaga inválido para pré-autorização.');

    const companyUserId: string = job.company_id;

    // --- Buscar método de pagamento default da empresa ---
    const { data: pm, error: pmErr } = await supabaseAdmin
      .from('payment_methods')
      .select('asaas_credit_card_token, brand, last4')
      .eq('company_id', companyUserId)
      .eq('is_default', true)
      .maybeSingle();

    if (pmErr || !pm) {
      throw new Error(
        'A empresa não possui método de pagamento cadastrado. ' +
        'Solicite ao operador que cadastre um cartão antes de aceitar convites.'
      );
    }

    // --- Buscar asaas_customer_id da empresa ---
    const { data: companyWallet, error: cwErr } = await supabaseAdmin
      .from('wallets')
      .select('asaas_customer_id')
      .eq('user_id', companyUserId)
      .maybeSingle();

    if (cwErr || !companyWallet?.asaas_customer_id) {
      throw new Error('Conta de pagamento da empresa não encontrada no Asaas.');
    }

    // --- remoteIp (exigido pelo Asaas para cobrança com cartão) ---
    const remoteIp =
      req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
      req.headers.get('x-real-ip') ||
      '0.0.0.0';

    // dueDate = hoje + 1 dia (mínimo exigido pelo Asaas)
    const dueDate = new Date();
    dueDate.setDate(dueDate.getDate() + 1);
    const dueDateStr = dueDate.toISOString().split('T')[0];

    // --- POST /v3/payments com authorizeOnly:true ---
    const paymentRes = await fetch(`${ASAAS_API_URL}/payments`, {
      method: 'POST',
      headers: getAsaasHeaders(),
      body: JSON.stringify({
        customer: companyWallet.asaas_customer_id,
        billingType: 'CREDIT_CARD',
        value: amount,
        dueDate: dueDateStr,
        description: `Turno reservado: ${job.title}`,
        externalReference: jobId,
        authorizeOnly: true,
        creditCardToken: pm.asaas_credit_card_token,
        remoteIp,
      }),
    });

    const paymentData = await paymentRes.json();

    // --- Tratar falha: pré-auth não habilitada → fallback charge_on_demand ---
    if (!paymentRes.ok) {
      const errMsg: string =
        paymentData.errors?.[0]?.description || paymentData.error || '';
      const isPreAuthDisabled =
        errMsg.toLowerCase().includes('autoriza') ||
        errMsg.toLowerCase().includes('authorize') ||
        paymentRes.status === 422;

      if (isPreAuthDisabled) {
        console.warn(
          `[authorize-payment] Pré-auth não disponível (fallback charge_on_demand): ${errMsg}`
        );
        return new Response(
          JSON.stringify({ success: true, status: 'charge_on_demand', fallback: true, reason: errMsg }),
          { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
        );
      }
      throw new Error(errMsg || 'Erro ao criar pré-autorização no Asaas.');
    }

    const asaasPaymentId: string = paymentData.id;
    if (!asaasPaymentId) throw new Error('Asaas não retornou o id da cobrança.');

    // Status esperado: AUTHORIZED. Se não, logar mas prosseguir (Asaas pode retornar PENDING transitório)
    if (paymentData.status && paymentData.status !== 'AUTHORIZED') {
      console.warn(
        `[authorize-payment] Status Asaas inesperado: ${paymentData.status} para payment=${asaasPaymentId}`
      );
    }

    // --- Gravar escrow 'authorized'/'postpaid' no DB (RPC atômica) ---
    const { data: escrowId, error: rpcErr } = await supabaseAdmin.rpc(
      'authorize_escrow_postpago',
      {
        p_job_id: jobId,
        p_application_id: applicationId,
        p_amount: amount,
        p_asaas_payment_id: asaasPaymentId,
        p_company_user_id: companyUserId,
      }
    );

    if (rpcErr) {
      // 23505 = único violado (hold duplicado) — tratar como idempotente
      if (rpcErr.code === '23505') {
        console.warn(`[authorize-payment] Escrow duplicado (23505), tratando como idempotente.`);
        return new Response(
          JSON.stringify({ success: true, asaasPaymentId, status: 'authorized', idempotent: true }),
          { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
        );
      }
      // RPC falhou após criar o hold no Asaas — logar para reconciliação manual
      console.error(
        `[authorize-payment] RPC authorize_escrow_postpago falhou após hold criado. ` +
        `asaas_payment_id=${asaasPaymentId} job=${jobId}. Erro: ${rpcErr.message}`
      );
      throw new Error('Falha ao registrar escrow. O hold foi criado no Asaas — contacte o suporte.');
    }

    return new Response(
      JSON.stringify({
        success: true,
        escrowId,
        asaasPaymentId,
        status: 'authorized',
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
    );
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : 'Erro interno.';
    console.error('asaas-authorize-payment error:', msg);
    return new Response(
      JSON.stringify({ error: msg }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 400 }
    );
  }
});

/**
 * asaas-capture-payment — Captura o hold no Asaas e credita o worker na conclusão do turno.
 *
 * Fluxo postpago (Slice 2 / ADR-20260622-pagamento-postpago):
 *  Chamado pela empresa na conclusão do turno (espelha asaas-checkout para kind='postpaid').
 *  Também pode ser disparado por auto-processamento (cron — R9) após janela de carência.
 *
 *  Dois caminhos:
 *  A) Tem hold ativo (status='authorized'/'postpaid'):
 *     → captureAuthorizedPayment no Asaas → capture_escrow_postpago (credita worker).
 *  B) Sem hold (charge_on_demand / hold expirado):
 *     → charge direta com o token default da empresa → authorize_escrow_postpago + capture_escrow_postpago.
 *     (fallback — sem ADR adicional, mesmo gateway Asaas, Article 6 intacto.)
 *
 * Idempotência:
 *  - capture_escrow_postpago usa WHERE status='authorized' → double-capture não duplica crédito.
 *  - UNIQUE (wallet_id, reference_id) em wallet_transactions → idempotência do crédito.
 *
 * Deploy normal (com verify-jwt) — caller é a EMPRESA.
 * Article 10: service_role apenas no Deno.
 */

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'jsr:@supabase/supabase-js@2';
import { getCorsHeaders, ASAAS_API_URL, getAsaasHeaders } from '../_shared/asaas.ts';
import { isRateLimited } from '../_shared/rate-limit.ts';

serve(async (req) => {
  const corsHeaders = getCorsHeaders(req);

  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    );

    // --- Auth (caller = empresa) ---
    const authHeader = req.headers.get('Authorization');
    if (!authHeader) throw new Error('Missing Authorization header');
    const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : authHeader;
    const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(token);
    if (userError || !user) throw new Error('Invalid Token');

    if (isRateLimited(user.id, 'capture-payment', 5, 60_000)) {
      return new Response(
        JSON.stringify({ error: 'Muitas tentativas. Aguarde 1 minuto.' }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 429 }
      );
    }

    const { jobId, workerId } = await req.json();
    if (!jobId || !workerId) throw new Error('jobId e workerId são obrigatórios.');

    // --- Verificar que o caller é dono do job ---
    const { data: job, error: jobErr } = await supabaseAdmin
      .from('jobs')
      .select('company_id, budget, title')
      .eq('id', jobId)
      .maybeSingle();

    if (jobErr || !job) throw new Error('Vaga não encontrada.');
    if (job.company_id !== user.id) throw new Error('Não autorizado: você não é o dono desta vaga.');

    // --- Verificar application concluída ou checkout confirmado ---
    const { data: app, error: appErr } = await supabaseAdmin
      .from('applications')
      .select('worker_id, status, company_checkout_confirmed_at')
      .eq('job_id', jobId)
      .eq('worker_id', workerId)
      .in('status', ['in_progress', 'completed'])
      .maybeSingle();

    if (appErr || !app) {
      throw new Error('Candidatura não encontrada ou trabalho ainda não foi iniciado.');
    }
    if (app.status !== 'completed' && !app.company_checkout_confirmed_at) {
      throw new Error('O trabalho precisa estar concluído antes de liberar o pagamento.');
    }

    // --- Get-or-create carteira do worker ---
    let workerWalletId: string;
    const { data: workerWallet } = await supabaseAdmin
      .from('wallets')
      .select('id')
      .eq('user_id', workerId)
      .maybeSingle();

    if (workerWallet) {
      workerWalletId = workerWallet.id;
    } else {
      const { data: newWallet, error: createErr } = await supabaseAdmin
        .from('wallets')
        .insert({ user_id: workerId, balance: 0, user_type: 'worker' })
        .select('id')
        .single();
      if (createErr || !newWallet) throw new Error('Falha ao criar carteira do worker.');
      workerWalletId = newWallet.id;
    }

    // --- Buscar escrow postpago 'authorized' ---
    const { data: escrow } = await supabaseAdmin
      .from('escrow_transactions')
      .select('id, asaas_payment_id, amount, status, captured_at')
      .eq('job_id', jobId)
      .eq('kind', 'postpaid')
      .maybeSingle();

    // --- Caminho A: tem hold ativo → capturar ---
    if (escrow && escrow.status === 'authorized' && escrow.asaas_payment_id) {
      const asaasPaymentId: string = escrow.asaas_payment_id;

      // captureAuthorizedPayment no Asaas
      const captureRes = await fetch(
        `${ASAAS_API_URL}/payments/${asaasPaymentId}/captureAuthorizedPayment`,
        {
          method: 'POST',
          headers: getAsaasHeaders(),
          body: JSON.stringify({}),
        }
      );
      const captureData = await captureRes.json();

      // Tratar hold expirado (fallback charge_on_demand)
      const isHoldExpired =
        !captureRes.ok &&
        (captureData.errors?.[0]?.description?.toLowerCase().includes('expir') ||
          captureData.errors?.[0]?.code === 'invalid_action' ||
          captureRes.status === 400);

      if (isHoldExpired) {
        console.warn(
          `[capture-payment] Hold expirado (job=${jobId}), executando charge_on_demand.`
        );
        return await chargeOnDemand(
          supabaseAdmin,
          jobId,
          app.worker_id ?? workerId,
          workerWalletId,
          job.company_id,
          job.budget,
          job.title,
          req,
          corsHeaders
        );
      }

      if (!captureRes.ok) {
        throw new Error(
          captureData.errors?.[0]?.description ||
          captureData.error ||
          'Erro ao capturar cobrança no Asaas.'
        );
      }

      // RPC atômica: marca released + credita worker (idempotente por (wallet_id, reference_id))
      const { error: rpcErr } = await supabaseAdmin.rpc('capture_escrow_postpago', {
        p_job_id: jobId,
        p_worker_wallet_id: workerWalletId,
      });

      if (rpcErr) {
        // Erro após captura no Asaas — logar para reconciliação
        console.error(
          `[capture-payment] RPC capture_escrow_postpago falhou após captura Asaas. ` +
          `job=${jobId} asaas_payment_id=${asaasPaymentId}. Erro: ${rpcErr.message}`
        );
        throw new Error('Falha ao registrar crédito. Pagamento foi capturado — contacte o suporte.');
      }

      return new Response(
        JSON.stringify({ success: true }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
      );
    }

    // --- Escrow já capturado/released → idempotente ---
    if (escrow && (escrow.status === 'released' || escrow.status === 'captured')) {
      return new Response(
        JSON.stringify({ success: true, idempotent: true }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
      );
    }

    // --- Caminho B: sem hold (charge_on_demand / job postpago sem pré-auth) ---
    if (!escrow || escrow.status === 'refunded') {
      return await chargeOnDemand(
        supabaseAdmin,
        jobId,
        workerId,
        workerWalletId,
        job.company_id,
        job.budget,
        job.title,
        req,
        corsHeaders
      );
    }

    throw new Error(`Estado de escrow inesperado: ${escrow?.status ?? 'ausente'}.`);
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : 'Erro interno.';
    console.error('asaas-capture-payment error:', msg);
    return new Response(
      JSON.stringify({ error: msg }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 400 }
    );
  }
});

// ---------------------------------------------------------------------------
// Charge-on-demand: cobrança direta com token (sem hold prévio).
// Usado quando: modo charge_on_demand, hold expirado, ou sem pré-auth disponível.
// ---------------------------------------------------------------------------

async function chargeOnDemand(
  // deno-lint-ignore no-explicit-any
  supabaseAdmin: any,
  jobId: string,
  workerId: string,
  workerWalletId: string,
  companyUserId: string,
  amount: number,
  jobTitle: string,
  req: Request,
  corsHeaders: Record<string, string>
): Promise<Response> {
  // Buscar token default da empresa
  const { data: pm, error: pmErr } = await supabaseAdmin
    .from('payment_methods')
    .select('asaas_credit_card_token')
    .eq('company_id', companyUserId)
    .eq('is_default', true)
    .maybeSingle();

  if (pmErr || !pm) {
    throw new Error('Método de pagamento da empresa não encontrado para cobrança direta.');
  }

  const { data: companyWallet } = await supabaseAdmin
    .from('wallets')
    .select('asaas_customer_id')
    .eq('user_id', companyUserId)
    .maybeSingle();

  if (!companyWallet?.asaas_customer_id) {
    throw new Error('Conta Asaas da empresa não encontrada.');
  }

  const remoteIp =
    req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
    req.headers.get('x-real-ip') ||
    '0.0.0.0';

  const dueDate = new Date();
  dueDate.setDate(dueDate.getDate() + 1);

  // Cobrança direta (sem authorizeOnly)
  const chargeRes = await fetch(`${ASAAS_API_URL}/payments`, {
    method: 'POST',
    headers: getAsaasHeaders(),
    body: JSON.stringify({
      customer: companyWallet.asaas_customer_id,
      billingType: 'CREDIT_CARD',
      value: amount,
      dueDate: dueDate.toISOString().split('T')[0],
      description: `Pagamento de turno: ${jobTitle}`,
      externalReference: jobId,
      creditCardToken: pm.asaas_credit_card_token,
      remoteIp,
    }),
  });

  const chargeData = await chargeRes.json();
  if (!chargeRes.ok) {
    throw new Error(
      chargeData.errors?.[0]?.description ||
      chargeData.error ||
      'Erro ao cobrar cartão da empresa.'
    );
  }

  const asaasPaymentId: string = chargeData.id;

  // Buscar carteira da empresa para authorize_escrow_postpago
  const { data: escrowExists } = await supabaseAdmin
    .from('escrow_transactions')
    .select('id')
    .eq('job_id', jobId)
    .eq('kind', 'postpaid')
    .maybeSingle();

  // Se não há escrow (charge_on_demand original), criar e capturar no mesmo passo
  if (!escrowExists) {
    // Buscar applicationId para authorize_escrow
    const { data: application } = await supabaseAdmin
      .from('applications')
      .select('id')
      .eq('job_id', jobId)
      .eq('worker_id', workerId)
      .maybeSingle();

    const applicationId = application?.id ?? null;

    // 1. Authorize (grava o escrow)
    const { error: authRpcErr } = await supabaseAdmin.rpc('authorize_escrow_postpago', {
      p_job_id: jobId,
      p_application_id: applicationId,
      p_amount: amount,
      p_asaas_payment_id: asaasPaymentId,
      p_company_user_id: companyUserId,
    });

    if (authRpcErr && authRpcErr.code !== '23505') {
      console.error(`[charge-on-demand] authorize_escrow_postpago falhou: ${authRpcErr.message}`);
      throw new Error('Falha ao registrar escrow após cobrança. Contacte o suporte.');
    }
  }

  // 2. Capture (credita worker — idempotente)
  const { error: capRpcErr } = await supabaseAdmin.rpc('capture_escrow_postpago', {
    p_job_id: jobId,
    p_worker_wallet_id: workerWalletId,
  });

  if (capRpcErr) {
    console.error(
      `[charge-on-demand] capture_escrow_postpago falhou após cobrança Asaas. ` +
      `job=${jobId} payment=${asaasPaymentId}. Erro: ${capRpcErr.message}`
    );
    throw new Error('Falha ao registrar crédito após cobrança. Contacte o suporte.');
  }

  return new Response(
    JSON.stringify({ success: true, chargeOnDemand: true }),
    { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
  );
}

/**
 * asaas-release-hold — Libera o hold no Asaas (cancelamento / no-show antes da captura).
 *
 * Fluxo postpago (Slice 2 / ADR-20260622-pagamento-postpago):
 *  Chamado pela empresa para cancelar o turno ou registrar no-show ANTES da conclusão.
 *  Marca o escrow como 'refunded' no DB (RPC release_hold_postpago) e deleta/libera
 *  o hold no Asaas (DELETE /v3/payments/{id}).
 *
 * Idempotência:
 *  - release_hold_postpago usa WHERE status='authorized' → não estorna hold já capturado.
 *  - Se o escrow já está 'refunded', retorna success sem reprocessar.
 *
 * Deploy normal (com verify-jwt) — caller é a EMPRESA.
 * Article 10: service_role apenas no Deno.
 */

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'jsr:@supabase/supabase-js@2';
import { getCorsHeaders, ASAAS_API_URL, getAsaasHeaders } from '../_shared/asaas.ts';
import { isRateLimited } from '../_shared/rate-limit.ts';

serve(async (req) => {
  const corsHeaders = getCorsHeaders(req);

  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    );

    // --- Auth (caller = empresa) ---
    const authHeader = req.headers.get('Authorization');
    if (!authHeader) throw new Error('Missing Authorization header');
    const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : authHeader;
    const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(token);
    if (userError || !user) throw new Error('Invalid Token');

    if (isRateLimited(user.id, 'release-hold', 5, 60_000)) {
      return new Response(
        JSON.stringify({ error: 'Muitas tentativas. Aguarde 1 minuto.' }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 429 }
      );
    }

    const { jobId, reason } = await req.json();
    if (!jobId) throw new Error('jobId é obrigatório.');

    // --- Verificar que o caller é dono do job ---
    const { data: job, error: jobErr } = await supabaseAdmin
      .from('jobs')
      .select('company_id')
      .eq('id', jobId)
      .maybeSingle();

    if (jobErr || !job) throw new Error('Vaga não encontrada.');
    if (job.company_id !== user.id) throw new Error('Não autorizado: você não é o dono desta vaga.');

    // --- Verificar estado atual do escrow (idempotência: já refunded = success) ---
    const { data: escrow } = await supabaseAdmin
      .from('escrow_transactions')
      .select('id, status, asaas_payment_id')
      .eq('job_id', jobId)
      .eq('kind', 'postpaid')
      .maybeSingle();

    // Sem escrow postpago para este job (job pode ser prepago ou sem hold)
    if (!escrow) {
      return new Response(
        JSON.stringify({ success: true, skipped: true, reason: 'Nenhum escrow postpago encontrado.' }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
      );
    }

    // Já liberado — idempotente
    if (escrow.status === 'refunded') {
      return new Response(
        JSON.stringify({ success: true, idempotent: true }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
      );
    }

    // Já capturado — não permitir liberar
    if (escrow.status === 'released' || escrow.status === 'captured') {
      throw new Error(
        'O pagamento já foi capturado e não pode ser estornado por esta operação. ' +
        'Utilize o processo de reembolso adequado.'
      );
    }

    if (escrow.status !== 'authorized') {
      throw new Error(`Estado de escrow inesperado para liberação: '${escrow.status}'.`);
    }

    // --- RPC: marcar 'refunded' no DB e obter asaas_payment_id ---
    const releaseReason = reason || 'Hold liberado (cancelamento/no-show)';
    const { data: rpcResult, error: rpcErr } = await supabaseAdmin.rpc(
      'release_hold_postpago',
      {
        p_job_id: jobId,
        p_reason: releaseReason,
      }
    );

    if (rpcErr) {
      // Se a RPC falhou porque não há hold authorized (race condition — outro processo liberou antes)
      if (rpcErr.message?.includes('Nenhum hold autorizado')) {
        return new Response(
          JSON.stringify({ success: true, idempotent: true }),
          { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
        );
      }
      throw new Error(rpcErr.message || 'Erro ao liberar escrow no banco de dados.');
    }

    // A RPC retorna TABLE(escrow_id, asaas_payment_id) — supabase-js retorna array
    const row = Array.isArray(rpcResult) ? rpcResult[0] : rpcResult;
    const asaasPaymentId: string | null = row?.asaas_payment_id ?? escrow.asaas_payment_id ?? null;

    // --- Liberar/deletar o hold no Asaas ---
    if (asaasPaymentId) {
      const deleteRes = await fetch(`${ASAAS_API_URL}/payments/${asaasPaymentId}`, {
        method: 'DELETE',
        headers: getAsaasHeaders(),
      });

      if (!deleteRes.ok) {
        const deleteData = await deleteRes.json().catch(() => ({}));
        const errMsg: string =
          deleteData.errors?.[0]?.description ||
          deleteData.error ||
          `HTTP ${deleteRes.status}`;

        // Hold já expirado no Asaas ou já deletado — não é erro crítico (DB já está correto)
        const isAlreadyGone =
          deleteRes.status === 404 ||
          errMsg.toLowerCase().includes('not found') ||
          errMsg.toLowerCase().includes('já cancelad');

        if (isAlreadyGone) {
          console.warn(
            `[release-hold] Hold já removido no Asaas (${errMsg}) — DB marcado como refunded. OK.`
          );
        } else {
          // Logar mas não lançar: o DB está correto (refunded), o hold será expirado naturalmente
          console.error(
            `[release-hold] Falha ao deletar hold no Asaas: ${errMsg}. ` +
            `payment=${asaasPaymentId}. DB correto — hold expirará em 3 dias.`
          );
        }
      }
    }

    return new Response(
      JSON.stringify({ success: true }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
    );
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : 'Erro interno.';
    console.error('asaas-release-hold error:', msg);
    return new Response(
      JSON.stringify({ error: msg }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 400 }
    );
  }
});

/**
 * PaymentMethodService — gerencia métodos de pagamento on-file da empresa (cartão tokenizado).
 *
 * Slice 2 / ADR-20260622-pagamento-postpago.
 * PCI / Article 10: o PAN nunca toca o banco — só o token opaco do Asaas + metadados.
 *
 * Padrão de imports: relativo sem alias @/ (padrão do projeto).
 * Padrão de fetch: invokeFunction para operações privilegiadas; supabase direto para leituras.
 */

import { supabase } from '../lib/supabase';
import { invokeFunction } from './api';
import { logError } from '../lib/logger';
import type { PaymentMethod } from '../types';

// ---------------------------------------------------------------------------
// Tipos de input/output da UI de cartão
// ---------------------------------------------------------------------------

/**
 * Dados necessários para tokenizar um cartão de crédito.
 * O PAN (number, ccv) trafega APENAS nesta chamada, server→Asaas.
 * NUNCA persiste no DB do Worki.
 */
export interface SaveCardInput {
  holderName: string;
  /** PAN completo — vai direto para o Asaas, não é gravado. */
  number: string;
  /** MM */
  expiryMonth: string;
  /** YYYY ou YY */
  expiryYear: string;
  /** CVV/CVC */
  ccv: string;
  holderInfo: {
    name: string;
    email: string;
    /** CPF ou CNPJ (só dígitos ou formatado — a Edge Function limpa). */
    cpfCnpj: string;
    /** CEP (só dígitos ou formatado). */
    postalCode: string;
    addressNumber: string;
    phone: string;
  };
}

export interface SaveCardResult {
  success: boolean;
  paymentMethodId?: string;
  brand?: string | null;
  last4?: string | null;
  error?: string;
}

export interface CapturePaymentResult {
  success: boolean;
  error?: string;
  chargeOnDemand?: boolean;
}

export interface ReleaseHoldResult {
  success: boolean;
  error?: string;
}

// ---------------------------------------------------------------------------
// Service
// ---------------------------------------------------------------------------

export const PaymentMethodService = {
  /**
   * Tokeniza e salva um cartão de crédito da empresa.
   *
   * Invoca a Edge Function `asaas-tokenize-card` (Article 10: PAN não passa pelo DB).
   * Idempotente: re-tokenizar o mesmo cartão não cria linha duplicada (UNIQUE company+token).
   *
   * @param input Dados do cartão (PAN + holderInfo).
   * @returns { success, paymentMethodId, brand, last4 } ou { success: false, error }.
   */
  async savePaymentMethod(input: SaveCardInput): Promise<SaveCardResult> {
    try {
      const result = await invokeFunction<{
        success: boolean;
        paymentMethodId?: string;
        brand?: string | null;
        last4?: string | null;
        error?: string;
      }>('asaas-tokenize-card', input as unknown as Record<string, unknown>);

      if (!result.success) {
        return { success: false, error: result.error || 'Erro ao salvar cartão.' };
      }

      return {
        success: true,
        paymentMethodId: result.paymentMethodId,
        brand: result.brand,
        last4: result.last4,
      };
    } catch (error: unknown) {
      logError('paymentMethodService.savePaymentMethod', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Erro ao salvar cartão.',
      };
    }
  },

  /**
   * Lista os métodos de pagamento cadastrados pela empresa autenticada.
   * Leitura direta via supabase (RLS garante isolamento por dono).
   */
  async listPaymentMethods(): Promise<PaymentMethod[]> {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return [];

      // Resolver company_id a partir do owner_id
      const { data: company, error: companyErr } = await supabase
        .from('companies')
        .select('id')
        .eq('owner_id', user.id)
        .maybeSingle();

      if (companyErr || !company) return [];

      const { data, error } = await supabase
        .from('payment_methods')
        .select('id, company_id, brand, last4, holder_name, is_default, created_at, updated_at')
        .eq('company_id', company.id)
        .order('is_default', { ascending: false })
        .order('created_at', { ascending: false });

      if (error) {
        logError('paymentMethodService.listPaymentMethods', error);
        return [];
      }

      // Não expor asaas_credit_card_token na listagem (PCI — token opaco, mas desnecessário na UI)
      return (data ?? []) as PaymentMethod[];
    } catch (error: unknown) {
      logError('paymentMethodService.listPaymentMethods', error);
      return [];
    }
  },

  /**
   * Retorna o método de pagamento default da empresa autenticada, ou null.
   */
  async getDefaultPaymentMethod(): Promise<PaymentMethod | null> {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return null;

      const { data: company } = await supabase
        .from('companies')
        .select('id')
        .eq('owner_id', user.id)
        .maybeSingle();

      if (!company) return null;

      const { data } = await supabase
        .from('payment_methods')
        .select('id, company_id, brand, last4, holder_name, is_default, created_at, updated_at')
        .eq('company_id', company.id)
        .eq('is_default', true)
        .maybeSingle();

      return (data as PaymentMethod | null);
    } catch (error: unknown) {
      logError('paymentMethodService.getDefaultPaymentMethod', error);
      return null;
    }
  },

  /**
   * Captura o pagamento postpago de um turno concluído.
   *
   * Para turnos kind='postpaid': invoca asaas-capture-payment (captura o hold ou charge_on_demand).
   * NÃO deve ser chamado para turnos prepago (esses usam WalletService.releaseEscrow).
   *
   * Idempotente: recapturar não duplica crédito.
   */
  async capturePayment(jobId: string, workerId: string): Promise<CapturePaymentResult> {
    try {
      const result = await invokeFunction<{ success: boolean; chargeOnDemand?: boolean; error?: string }>(
        'asaas-capture-payment',
        { jobId, workerId }
      );

      return {
        success: result.success,
        chargeOnDemand: result.chargeOnDemand,
      };
    } catch (error: unknown) {
      logError('paymentMethodService.capturePayment', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Erro ao capturar pagamento.',
      };
    }
  },

  /**
   * Libera o hold postpago (cancelamento / no-show antes da captura).
   * Invoca asaas-release-hold (RPC release_hold_postpago + DELETE no Asaas).
   * Idempotente: escrow já refunded → success silencioso.
   */
  async releaseHold(jobId: string, reason?: string): Promise<ReleaseHoldResult> {
    try {
      await invokeFunction('asaas-release-hold', {
        jobId,
        reason: reason ?? 'Cancelamento/no-show antes da conclusão',
      });
      return { success: true };
    } catch (error: unknown) {
      logError('paymentMethodService.releaseHold', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Erro ao liberar hold.',
      };
    }
  },
};

