// ---------------------------------------------------------------------------
// Helper interno: disparar pré-autorização postpago (best-effort, não bloqueia o aceite)
// ---------------------------------------------------------------------------

/**
 * Invoca asaas-authorize-payment após o aceite do convite.
 * Falha NÃO reverte o status 'hired' — o aceite já aconteceu no DB.
 * O fallback charge_on_demand (env ASAAS_POSTPAGO_MODE) é tratado dentro da Edge Function.
 * Erros são logados para reconciliação.
 */
async function dispatchAuthorizePayment(
  jobId: string,
  applicationId: string,
): Promise<void> {
  try {
    await invokeFunction('asaas-authorize-payment', { jobId, applicationId });
  } catch (authErr) {
    // Logar mas NÃO propagar — o aceite (status 'hired') é o evento principal.
    // A captura fallback charge_on_demand ocorre na conclusão.
    logError('shiftInvite.authorizePayment (best-effort)', authErr);
  }
}

